begin;
create index if not exists canonical_targets_club_import_key_v176 on public.canonical_targets((editorial_metadata->>'club_import_key')) where editorial_metadata ? 'club_import_key';
create index if not exists canonical_targets_club_branch_v176 on public.canonical_targets((editorial_metadata->'club_hierarchy'->>'parent_target_id'),(editorial_metadata->'club_hierarchy'->>'sport'),(editorial_metadata->'club_hierarchy'->>'division')) where editorial_metadata->>'content_type_id'='club';
create or replace function public.import_club_group_v176(g jsonb) returns uuid language plpgsql security definer set search_path=public,pg_temp as $fn$
declare root_id uuid; seed_type uuid; team jsonb; original_team jsonb; child_id uuid; profile jsonb; teams jsonb; key_id text; root_row public.canonical_targets%rowtype; competition jsonb; sources jsonb;
begin
 if auth.uid() is null or not public.is_admin() then raise exception 'Administrator required';end if;
 select id into seed_type from public.seed_types where slug='live-performance' and is_active;
 root_id:=nullif(g->>'existing_root','')::uuid;
 if root_id is null then
  select id into root_id from public.canonical_targets where editorial_metadata->>'club_import_key'=public.canonical_normalize_v31(g->>'name') limit 1;
 end if;
 if root_id is null then
  select ci.canonical_target_id into root_id from public.seed_catalog_items ci join public.canonical_targets ct on ct.id=ci.canonical_target_id where ci.item_kind='club' and ci.status='active' and ci.normalized_title=public.normalize_seed_catalog_text(g->>'name') and nullif(ct.editorial_metadata->'club_hierarchy'->>'parent_target_id','') is null limit 1;
 end if;
 if root_id is null then
  root_id:=public.admin_create_club_card_v75(seed_type,'club',g->>'name',null,g->>'logo_url',null,coalesce(g->>'club_source',g->'references'->>0),jsonb_build_object('logo_url',g->>'logo_url','teams','[]'::jsonb));
 end if;
 select * into root_row from public.canonical_targets where id=root_id;
 profile:=coalesce(root_row.editorial_metadata->'club_profile','{}'::jsonb);
 profile:=profile||jsonb_build_object('logo_url',coalesce(nullif(profile->>'logo_url',''),g->>'logo_url'));
 teams:=coalesce(profile->'teams','[]'::jsonb);
 for team in select value from jsonb_array_elements(g->'teams') loop
  child_id:=null;original_team:=null;
  select id into child_id from public.canonical_targets where editorial_metadata->>'content_type_id'='club' and editorial_metadata->'club_hierarchy'->>'parent_target_id'=root_id::text and lower(editorial_metadata->'club_hierarchy'->>'sport')=lower(team->>'sport') and lower(editorial_metadata->'club_hierarchy'->>'division')=lower(team->>'division') limit 1;
  if child_id is not null then
   select editorial_metadata->'club_hierarchy'->>'profile_team_id' into key_id from public.canonical_targets where id=child_id;
   select value into original_team from jsonb_array_elements(teams) where value->>'id'=key_id limit 1;
  else key_id:='catalogue_v176_'||md5(root_id::text||':'||(team->>'sport')||':'||(team->>'division'));
  end if;
  team:=coalesce(original_team,'{}'::jsonb)||(team-'competitions'-'sources')||jsonb_build_object('id',key_id,'logo_url',coalesce(nullif(original_team->>'logo_url',''),profile->>'logo_url'));
  select coalesce(jsonb_agg(value),'[]'::jsonb) into teams from jsonb_array_elements(teams) where value->>'id'<>key_id;
  teams:=teams||jsonb_build_array(team);
 end loop;
 profile:=profile||jsonb_build_object('teams',teams);
 perform public.admin_save_club_card_v75(root_id,root_row.title,'club',null,coalesce(nullif(root_row.editorial_cover_url,''),g->>'logo_url'),root_row.editorial_metadata->>'description',coalesce(root_row.editorial_metadata->>'reference_url',g->>'club_source',g->'references'->>0),profile,coalesce((root_row.editorial_metadata->>'cover_position_y')::numeric,50),coalesce(root_row.editorial_metadata->'club_hierarchy','{}'::jsonb));
 update public.canonical_targets set editorial_metadata=editorial_metadata||jsonb_build_object('club_import_key',public.canonical_normalize_v31(g->>'name'),'catalogue_sources',g->'references','catalogue_as_of','2026-10-12') where id=root_id;
 for team in select value from jsonb_array_elements(g->'teams') loop
  select id into child_id from public.canonical_targets where editorial_metadata->>'content_type_id'='club' and editorial_metadata->'club_hierarchy'->>'parent_target_id'=root_id::text and lower(editorial_metadata->'club_hierarchy'->>'sport')=lower(team->>'sport') and lower(editorial_metadata->'club_hierarchy'->>'division')=lower(team->>'division') limit 1;
  if child_id is null then raise exception 'Missing branch for %',g->>'name';end if;
  select coalesce(jsonb_agg(distinct x),'[]'::jsonb) into competition from jsonb_array_elements(coalesce((select editorial_metadata->'club_competitions' from public.canonical_targets where id=child_id),'[]'::jsonb)||coalesce(team->'competitions','[]'::jsonb))x;
  update public.canonical_targets set editorial_metadata=editorial_metadata||jsonb_build_object('club_competitions',competition,'catalogue_sources',team->'sources','catalogue_as_of','2026-10-12') where id=child_id;
  update public.seed_catalog_items set metadata=metadata||jsonb_build_object('club_competitions',competition,'catalogue_sources',team->'sources','catalogue_as_of','2026-10-12') where canonical_target_id=child_id;
 end loop;
 return root_id;
end;$fn$;
revoke all on function public.import_club_group_v176(jsonb) from public,anon,authenticated;
commit;
